import type {G2Lesson, G2Observations, G2Point, G2Slot, G2TaskState} from './g2-u1-scratch-lessons'

export const L07_CAT_START: G2Point = {x: -160, y: -80}
export const L07_DOOR_ZONE = {minX: 100, maxX: 170} as const
export const L07_CAT_LINE = '我到家啦！'
export const L07_WALK_FRAMES = ['走路1', '走路2', '走路3', '走路4']
/** Average time between two costume frames below which the walk is a blur (VM-measured, ms). */
export const L07_TOO_FAST_MS = 100
/** Average time between two frames from which each leg position can be seen (ms). */
export const L07_VISIBLE_MS = 150

export function atDoor(point: G2Point | undefined | null): boolean {
  return !!point && Number.isFinite(point.x) && point.x >= L07_DOOR_ZONE.minX && point.x <= L07_DOOR_ZONE.maxX
}

