type FrameRun = G2Observations['frameRuns'][number]
const catFrames = (run: FrameRun) => run.frames['小橘猫']
const fullCycle = (run: FrameRun) => { const f = catFrames(run); return !!f && f.count >= 4 && f.end === '走路1' }
const visible = (run: FrameRun) => { const f = catFrames(run); return !!f && f.avgMs !== null && f.avgMs >= L07_VISIBLE_MS }
const tooFast = (run: FrameRun) => { const f = catFrames(run); return !!f && f.avgMs !== null && f.avgMs < L07_TOO_FAST_MS }

export function evaluateG2U2L01(obs: G2Observations): G2TaskState {
  const runs = obs.frameRuns.filter(r => !!catFrames(r))
  const firstFast = runs.findIndex(tooFast)
  const line = obs.lastSaid['小橘猫']
  return {
    practiceA: runs.some(fullCycle),
    practiceB: runs.some(r => atDoor(r.positions['小橘猫'])),
    debug: firstFast >= 0 && runs.slice(firstFast + 1).some(visible),
    create: !!line && line !== L07_CAT_LINE && runs.some(r => fullCycle(r) && visible(r) && atDoor(r.positions['小橘猫'])),
  }
}

export function observedPredictionG2U2(id: string, obs: G2Observations): string | null {
  if (id === g2u2L01.id) {
    const first = obs.frameRuns.find(r => catFrames(r)?.avgMs !== null && catFrames(r)?.avgMs !== undefined)
    if (!first) return null
    const ms = catFrames(first)!.avgMs!
    return ms < L07_TOO_FAST_MS ? '快得看不清' : ms >= L07_VISIBLE_MS ? '看得清' : null
  }
  return null
}

export function evaluateG2U2Lesson(id: string, obs: G2Observations): G2TaskState | null {
  if (id === g2u2L01.id) return evaluateG2U2L01(obs)
  return null
}

export const g2u2ScratchLessons: Record<string, G2Lesson> = {
  [g2u2L01.id]: g2u2L01,
}
